        return self.F_initial + np.random.uniform(-self.F_adaptive_rate, self.F_adaptive_rate)

    def adaptive_scaling_cr(self):
        return self.CR_initial + np.random.uniform(-self.CR_adaptive_rate, self.CR_adaptive_rate)

